// Loop Unrolling (Reduces branch overhead and pipeline stalls)
// Factor 4 Unrolling example
for (int i = 0; i < N; i += 4) {
    A[i] = B[i];
    A[i+1] = B[i+1];
    A[i+2] = B[i+2];
    A[i+3] = B[i+3];
}

// Strength Reduction (Replacing multiplication with addition)
// Original: A[i * 4]
int offset = 0;
for (int i = 0; i < N; i++) {
    A[offset] = X[i];
    offset += 4; // Add is cheaper than Multiply
}

// Loop Invariant Code Motion (LICM)
// Calculation moved outside the loop scope
const int INVARIANT = X * Y + Z; // Expensive operation

for (int i = 0; i < N; i++) {
    // result[i] = (X * Y + Z) + i; // Original location
    result[i] = INVARIANT + i;
}

// SIMD Vectorization Hint (Data-level parallelism)
// Requires consecutive memory access/data independence
